pub(super) const PETITION_ADMIN_ADMIN_HTML: &str = concat!(
    "<div class=\"petition-admin-module-box\" id=\"petition-admin-module-box\"><h1>Administer your petition campaigns</h1>\n",
    "    \n",
    "            <p>\n",
    "            You have no petition campaigns defined.        </p>\n",
    "        <p>\n",
    "        <a href=\"javascript:;\" onclick=\"WIKIDOT.modules.PetitionAdminModule.listeners.newCampaignClick(event)\">+ Create a new campaign</a>\n",
    "    </p>\n",
    "    \n",
    "    <div id=\"petition-new-campain-box\" style=\"display: none\">\n",
    "        <h2>Create a new campaign</h2>\n",
    "        \n",
    "        <form id=\"petition-new-campain-form\">\n",
    "            <div class=\"error-block\" id=\"petition-new-campaign-error-box\" style=\"display: none\"></div>\n",
    "            <table class=\"form\">\n",
    "                <tr>\n",
    "                    <td>\n",
    "                        Name:\n",
    "                    </td>\n",
    "                    <td>\n",
    "                        <input type=\"text\" class=\"text\" name=\"name\" size=\"30\" value=\"\"/>\n",
    "                    </td>\n",
    "                </tr>\n",
    "                <tr>\n",
    "                    <td>\n",
    "                        Identifier:\n",
    "                    </td>\n",
    "                    <td>\n",
    "                        <input type=\"text\" class=\"text\" name=\"identifier\" size=\"30\" value=\"\"/>\n",
    "                        <div class=\"sub\">\n",
    "                            Only letters and numbers allowed, e.g. <em>p01</em>. This will be used to point other modules<br/>                                 to the particular campaign with the <em>id=\"...\"</em> attribute.                        </div>\n",
    "                    </td>\n",
    "                </tr>\n",
    "            </table>\n",
    "            \n",
    "            <div class=\"buttons\">\n",
    "                <input type=\"button\" value=\"Cancel\" onclick=\"WIKIDOT.modules.PetitionAdminModule.listeners.cancelNewCampaignClick(event)\"/>\n",
    "                <input type=\"button\" value=\"Create\" onclick=\"WIKIDOT.modules.PetitionAdminModule.listeners.createCampaign(event)\" />\n",
    "                \n",
    "            </div>\n",
    "        </form>\n",
    "    \n",
    "    </div>\n",
    "</div>",
);
